input.command:
createdb etl_edge 2>&1 && export PGDATABASE=etl_edge && psql -q -v ON_ERROR_STOP=1 -f source/schema.sql 2>/dev/null && psql -q -v ON_ERROR_STOP=1 -f dashboard_schema.sql 2>/dev/null && python3 source/seed.py --rows 2000 --print-only | psql -q -v ON_ERROR_STOP=1 && psql -q -v ON_ERROR_STOP=1 <<'SQL'
-- multi-category COMPLETED order: first line HARDWARE(cat of product 5 -> 5%5=0 => idx1 HARDWARE), second line SOFTWARE
INSERT INTO orders VALUES (900001, 1, '2026-03-10', 'COMPLETED', 0);
INSERT INTO order_items VALUES (9000010, 900001, 5, 2, 100.00);   -- product 5 => HARDWARE, controlling
INSERT INTO order_items VALUES (9000011, 900001, 4, 7, 1.00);     -- product 4 => SOFTWARE
-- COMPLETED order with no lines
INSERT INTO orders VALUES (900002, 2, '2026-03-11', 'COMPLETED', 0);
-- non-completed multi-category order must be ignored
INSERT INTO orders VALUES (900003, 3, '2026-03-12', 'CANCELLED', 0);
INSERT INTO order_items VALUES (9000030, 900003, 5, 1, 1.00);
INSERT INTO order_items VALUES (9000031, 900003, 4, 1, 1.00);
SQL
psql -v ON_ERROR_STOP=1 -f etl.sql >/dev/null && psql -v ON_ERROR_STOP=1 -f etl.sql > /dev/null && echo "two runs OK"
psql -c "select * from dash_revenue_by_category where month='2026-03' and category in ('HARDWARE','SOFTWARE','(no items)')" -c "select * from etl_run_log order by run_id"

